sys_script.script:
(function() {
    var taskId = current.getValue('task');
    if (!taskId) return;

    // Verify the task is a Security Case
    var caseGR = new GlideRecord('x_2241073_securi_0_sec_case');
    if (!caseGR.get(taskId)) return;

    // Query all active task_sla records for this case
    var slaGR = new GlideRecord('task_sla');
    slaGR.addQuery('task', taskId);
    slaGR.addQuery('active', true);
    slaGR.query();

    var responseDue = '';
    var resolutionDue = '';
    var worstStatus = 1; // 1=On Track

    while (slaGR.next()) {
        var slaDefName = slaGR.getDisplayValue('sla');
        var plannedEnd = slaGR.getValue('planned_end_time');
        var hasBreached = slaGR.getValue('has_breached');
        var percentage = parseFloat(slaGR.getValue('percentage')) || 0;

        // Determine SLA type from definition name
        if (slaDefName.indexOf('Response') > -1) {
            responseDue = plannedEnd || '';
        } else if (slaDefName.indexOf('Resolution') > -1) {
            resolutionDue = plannedEnd || '';
        }

        // Determine worst SLA status
        if (hasBreached == 'true' || hasBreached == true) {
            worstStatus = 3; // Breached
        } else if (percentage >= 80 && worstStatus < 2) {
            worstStatus = 2; // At Risk
        }
    }

    // Also check completed/breached SLAs
    var completedGR = new GlideRecord('task_sla');
    completedGR.addQuery('task', taskId);
    completedGR.addQuery('active', false);
    completedGR.addQuery('has_breached', true);
    completedGR.query();
    if (completedGR.hasNext()) {
        worstStatus = 3; // Breached
    }

    // Update the Security Case
    caseGR.setValue('sla_status', worstStatus.toString());
    if (responseDue) caseGR.setValue('response_due', responseDue);
    if (resolutionDue) caseGR.setValue('resolution_due', resolutionDue);
    caseGR.setWorkflow(false); // Prevent recursive BR firing
    caseGR.update();
})();
